INSERT INTO tool_catalog (id, tool_key, name, description, tool_type, risk_level, execution_mode, enabled, built_in, policy_json, parameter_schema_json, create_time, update_time) VALUES
(910103, 'READ_DIFF_SUMMARY', '读取 Diff 摘要', '只读读取指定基准分支与当前分支的差异摘要。不执行 git diff shell，不修改任何文件。', 'READ_ONLY', 'MEDIUM', 'MOCK_EXECUTE', 1, 1, '{"allowedStepTypes":["CODE_REVIEW","BACKEND_IMPLEMENTATION_PLAN","FRONTEND_IMPLEMENTATION_PLAN","FINAL_SUMMARY"],"readOnly":true,"allowShell":false,"allowGitWrite":false,"allowFileWrite":false}', '{"fields":[{"key":"branch","label":"分支","type":"text","required":false,"defaultValue":"","maxLength":128},{"key":"baseBranch","label":"基准分支","type":"text","required":false,"defaultValue":"main","maxLength":128},{"key":"maxFiles","label":"最大文件数","type":"number","required":true,"defaultValue":30,"min":1,"max":100}]}', NOW(), NOW())
ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), tool_type=VALUES(tool_type), risk_level=VALUES(risk_level), execution_mode=VALUES(execution_mode), enabled=VALUES(enabled), built_in=VALUES(built_in), policy_json=VALUES(policy_json), parameter_schema_json=VALUES(parameter_schema_json), update_time=NOW();

-- 910104: READ_BRANCH_INFO
INSERT INTO tool_catalog (id, tool_key, name, description, tool_type, risk_level, execution_mode, enabled, built_in, policy_json, parameter_schema_json, create_time, update_time) VALUES
(910104, 'READ_BRANCH_INFO', '读取分支信息', '只读查询项目仓库分支列表和基本信息。不执行 checkout，不执行 pull，不修改任何文件。', 'READ_ONLY', 'LOW', 'MOCK_EXECUTE', 1, 1, '{"allowedStepTypes":["CODE_REVIEW","ARCHITECTURE_ANALYSIS","FINAL_SUMMARY"],"readOnly":true,"allowShell":false,"allowGitWrite":false,"allowFileWrite":false}', '{"fields":[{"key":"includeRemote","label":"包含远程分支","type":"boolean","required":false,"defaultValue":true},{"key":"maxBranches","label":"最大分支数","type":"number","required":true,"defaultValue":30,"min":1,"max":100}]}', NOW(), NOW())
ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), tool_type=VALUES(tool_type), risk_level=VALUES(risk_level), execution_mode=VALUES(execution_mode), enabled=VALUES(enabled), built_in=VALUES(built_in), policy_json=VALUES(policy_json), parameter_schema_json=VALUES(parameter_schema_json), update_time=NOW();
